    return translationQueue.add('translate', { text, src, tgt }, { jobId: id, attempts: 5, backoff: { type: 'exponential', delay: 1000 }, removeOnComplete: true, removeOnFail: 1000 });
  }

  const worker = new Worker('translate', async (job) => {
