// server.js
import express from 'express';
import crypto from 'crypto';
import https from 'https';
import axios from 'axios';
import { createClient } from 'redis';

const app = express();
app.use(express.json());

// Redis v7
const redis = createClient({ url: process.env.REDIS_URL || 'redis://localhost:6379' });
await redis.connect();

// Axios client with keep-alive + tight timeouts
const httpsAgent = new https.Agent({ keepAlive: true, maxSockets: 200, timeout: 10_000 });
const http = axios.create({
  baseURL: 'https://api.deepl.com/v2',
  timeout: 1500, // keep this tight; rely on retries
  httpsAgent,
  headers: { 'Content-Type': 'application/x-www-form-urlencoded' }
});

const DEEPL_API_KEY = process.env.DEEPL_API_KEY;
const CACHE_TTL_SEC = 60 * 60 * 24; // 24h; translations are stable
const inflight = new Map(); // single-flight map by cache key

const sleep = (ms) => new Promise(r => setTimeout(r, ms));
const sha256 = (s) => crypto.createHash('sha256').update(s).digest('hex');
const normalize = (s) => s.trim().replace(/\s+/g, ' ');

// Retry wrapper with backoff + Retry-After
async function withRetries(fn, { maxRetries = 3, baseDelay = 200 } = {}) {
  let attempt = 0;
  while (true) {
    try {
      return await fn();
    } catch (err) {
      const status = err?.response?.status;
      const retryAfter = err?.response?.headers?.['retry-after'];
      if ((status === 429 || status >= 500) && attempt < maxRetries) {
        attempt++;
        let delay = retryAfter ? Number(retryAfter) * 1000 : baseDelay * 2 ** (attempt - 1);
        // add jitter
        delay = Math.min(2000, delay + Math.floor(Math.random() * 100));
        await sleep(delay);
        continue;
      }
      throw err;
    }
  }
}

// Call DeepL (supports batch via multiple "text" params)
async function deeplTranslate(texts, sourceLang, targetLang) {
  const params = new URLSearchParams();
  params.append('auth_key', DEEPL_API_KEY);
  for (const t of texts) params.append('text', t);
  params.append('target_lang', targetLang);
  if (sourceLang) params.append('source_lang', sourceLang); // set explicitly when known (EN/FR)

  const res = await withRetries(() => http.post('/translate', params));
  return res.data.translations.map(t => t.text);
}

// Single-flight wrapper
async function singleFlight(key, fn) {
  if (inflight.has(key)) return inflight.get(key);
  const p = (async () => {
    try {
      return await fn();
    } finally {
      inflight.delete(key);
    }
  })();
  inflight.set(key, p);
  return p;
}

// Generate compact cache key (hash large texts)
function cacheKey({ text, sourceLang, targetLang }) {
  const norm = normalize(text);
  const h = sha256(norm);
  return `trl:${sourceLang || 'auto'}:${targetLang}:${h}`;
}

// Fast path: single text
app.post('/translate/text', async (req, res) => {
  try {
    const { text, targetLang, sourceLang } = req.body || {};
    if (!text || !targetLang) return res.status(400).json({ error: 'text and targetLang are required' });

    // For your EN/FR preference, set sourceLang when known to skip auto-detect
    // e.g., if user preference stored per user: sourceLang in {EN, FR}
    const key = cacheKey({ text, sourceLang, targetLang });
    const cached = await redis.get(key);
    if (cached) return res.json({ translatedText: cached, cached: true });

    const result = await singleFlight(key, async () => {
      const [translated] = await deeplTranslate([normalize(text)], sourceLang, targetLang);
      // Store long TTL; Redis maxmemory-policy=allkeys-lru will evict least used
      await redis.setEx(key, CACHE_TTL_SEC, translated);
      return translated;
    });

    res.json({ translatedText: result, cached: false });
  } catch (err) {
    const status = err?.response?.status || 500;
    res.status(status >= 400 && status < 600 ? status : 500).json({ error: 'Translation failed' });
  }
});

// Batch: only send cache-misses to DeepL in one call
app.post('/translate/batch', async (req, res) => {
  try {
    const { texts, targetLang, sourceLang } = req.body || {};
    if (!Array.isArray(texts) || texts.length === 0 || !targetLang) {
      return res.status(400).json({ error: 'texts (array) and targetLang are required' });
    }

    // Check cache first
    const keys = texts.map(t => cacheKey({ text: t, sourceLang, targetLang }));
    const cached = await redis.mGet(keys);

    // Build miss list
    const misses = [];
    const missIdx = [];
    texts.forEach((t, i) => {
      if (!cached[i]) {
        misses.push(normalize(t));
        missIdx.push(i);
      }
    });

    let filled = [...(cached || [])];
    if (misses.length) {
      // Deduplicate in-flight per joined-key
      const flightKey = `batch:${sha256(JSON.stringify({ keys: missIdx.map(i => keys[i]) }))}`;

      const translatedMisses = await singleFlight(flightKey, async () => {
        const out = await deeplTranslate(misses, sourceLang, targetLang);
        // Write-back cache in parallel
        await Promise.all(out.map((tr, j) => redis.setEx(keys[missIdx[j]], CACHE_TTL_SEC, tr)));
        return out;
      });

      // Place back into full result
      translatedMisses.forEach((tr, j) => { filled[missIdx[j]] = tr; });
    }

    res.json({ translations: filled });
  } catch (err) {
    const status = err?.response?.status || 500;
    res.status(status >= 400 && status < 600 ? status : 500).json({ error: 'Batch translation failed' });
  }
});

app.listen(4500, () => console.log('Translation service listening on 4500'));
```

