```javascript
import https from 'https';
import crypto from 'crypto';
import axios from 'axios';
import { createClient } from 'redis';

const httpsAgent = new https.Agent({ keepAlive: true, maxSockets: 256, maxFreeSockets: 64 });

const deepl = axios.create({
  baseURL: 'https://api.deepl.com/v2',
  timeout: 1200,                 // keep tight; cache hits should return <10ms
  httpsAgent,
  headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
});

const redis = createClient({ url: process.env.REDIS_URL }); // redis://localhost:6379
await redis.connect();

const inflight = new Map(); // key -> Promise

function normKey(text, sourceLang, targetLang, provider = 'deepl') {
  const h = crypto.createHash('sha256').update(text).digest('hex');
  return `tr:v1:${provider}:${(sourceLang || 'auto').toUpperCase()}:${targetLang.toUpperCase()}:${h}`;
}

async function getCached(key) {
  const v = await redis.get(key);
  return v ? JSON.parse(v) : null;
}
async function setCached(key, value, ttlSec = 3600) {
  await redis.set(key, JSON.stringify(value), { EX: ttlSec });
}

function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

async function withRetry(fn) {
  const max = 3;
  let delay = 150;
  for (let i = 0; i <= max; i++) {
    try {
      return await fn();
    } catch (err) {
      const status = err?.response?.status;
      const retryAfter = Number(err?.response?.headers?.['retry-after']) * 1000 || 0;
      const retriable = status === 429 || (status >= 500 && status < 600);
      if (!retriable || i === max) throw err;
      await sleep(Math.max(retryAfter, delay + Math.floor(Math.random() * 50)));
      delay *= 2;
    }
  }
}

async function translateText({ text, sourceLang, targetLang }) {
  const key = normKey(text, sourceLang, targetLang, 'deepl');

  // 1) Cache first
  const cached = await getCached(key);
  if (cached) return cached; // ~sub-5ms

  // 2) In-flight de-dup
  if (inflight.has(key)) return inflight.get(key);

  const p = (async () => {
    // 3) Provider call with retry
    const params = new URLSearchParams();
    params.append('auth_key', process.env.DEEPL_API_KEY);
    params.append('text', text);
    params.append('target_lang', targetLang.toUpperCase());
    if (sourceLang) params.append('source_lang', sourceLang.toUpperCase());

    const result = await withRetry(async () => {
      const { data } = await deepl.post('/translate', params);
      return data?.translations?.[0]?.text;
    });

    const payload = { text: result, provider: 'deepl' };

    // 4) Cache result (tune TTLs)
    await setCached(key, payload, 60 * 60); // 1h

    return payload;
  })().finally(() => inflight.delete(key));

  inflight.set(key, p);
  return p;
}

// Example Express handler
