Protect the Node event loop (franc is CPU-bound)
- Offload detection to worker threads so you don’t block the event loop. Piscina is simple and fast.
  - Keep maxThreads at os.cpus().length; cap queue concurrency to cores.

Example (server)
const express = require('express');
const os = require('os');
const path = require('path');
const Piscina = require('piscina');

const app = express();
app.use(express.json({ limit: '8kb' })); // keep body small
const pool = new Piscina({
  filename: path.resolve(__dirname, 'detect-worker.js'),
  maxThreads: os.cpus().length
});

app.post('/api/language-detect', async (req, res) => {
  const text = req.body?.text || '';
  if (!text || text.length < 3) return res.status(400).json({ error: 'Invalid text' });

  try {
    const lang = await pool.run({ text });
    res.json({ language: lang });
  } catch (e) {
    // Backpressure hint: if queue is saturated, return 429 with Retry-After
    if (String(e.message || '').includes('Queue is at capacity')) {
      return res.status(429).set('Retry-After', '1').json({ error: 'Busy, retry soon' });
    }
    res.status(500).json({ error: 'Detection failed' });
  }
});

app.listen(3000);

